"""Derive SkyyHud/build_skyyhud_0.3.38.py from the LIVE SkyyHud 0.3.37 (build_skyyhud_0.3.37.py = the tools/deploy_set.py SET pin, generated by
tools/hud_0_3_37_patch.py - never edit a generated script, edit this patch). Every anchor is asserted; at the end every change is undone on a
copy and compared with 0.3.37 (nothing else changed; tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/hud_0_3_38_patch.py   then   python SkyyHud/build_skyyhud_0.3.38.py   (never --deploy)
Check: python SkyyHud/test_skyyhud_0.3.38.py [--dir <folder inside tools/dev/scratch/>] [--keep]
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.3.38 (2026-11-21, round pets1 fix) = THE PET CARD SHOWS THE FIGHTING PET'S HEALTH + ABILITY (SkyyPets 0.4.27, Skyy 2026-11-14 docs/answered/pets.md:
  "combat pets will attack when in pet slot. (pets that are all 3 like the dragon will stay around and fight in the pet slot, and just summon in the
  mount slot"). SkyyPets 0.4.27 sends the health / Bite fields on the PET slot line (the dragon fights from there now); 0.3.37 read them only from the
  second (summon / mount) line, so the fighting dragon showed no health. Now the health / ability block comes from the FIRST line that carries it
  (pet slot first, then the mount slot) and is drawn right under that card (shape letter q = under the pet card); the box height is the same sum.
  Older SkyyPets (0.4.20 - 0.4.26: the fields only on the second line) show exactly as in 0.3.37.
  Unchanged: every other widget, the Pets spot / size / samples, commands, permissions, config rows, saved data.
  NOT IN THIS ROUND: Skyy's v5 HUD layout (pet card left of the hotbar, mount card right, nothing over the vanilla compass) - its own round.
  ROLLBACK to 0.3.37: safe, no data step (the pet-slot dragon's health is then not shown).
'''

P = G.Patch(os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.37.py"), os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.38.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.3.37"') and P.has("petsModelOf") and not P.has("0.3.38: the health / ability block"), "not the generated SkyyHud 0.3.37 script"
SYS0, CMD0 = P.s.count("registerSystem("), P.s.count("registerCommand(")

P.rep('''"""SkyyHud 0.3.37 - build script (javassist via jpype). GENERATED by tools/hud_0_3_37_patch.py from the LIVE 0.3.36 - edit the patch.
Run:   python build_skyyhud_0.3.37.py            -> SkyyHud/SkyyHud-0.3.37.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.37.py
''', '''"""SkyyHud 0.3.38 - build script (javassist via jpype). GENERATED by tools/hud_0_3_38_patch.py from the LIVE 0.3.37 - edit the patch.
Run:   python build_skyyhud_0.3.38.py            -> SkyyHud/SkyyHud-0.3.38.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.38.py
''' + NOTE + '''0.3.37 (generated by tools/hud_0_3_37_patch.py from 0.3.36):
''')
P.rep('VERSION = "0.3.37"\n', 'VERSION = "0.3.38"\n')

# ---- petsModelOf: the block from the first line that carries it
P.rep('''  String tail = "";
  for (int s = 0; s < 2 && s < a.length; s++) {
    String ln = a[s];''', '''  String tail = "";
  boolean blk = false;          // 0.3.38: the health / ability block is taken once
  for (int s = 0; s < 2 && s < a.length; s++) {
    String ln = a[s];''')
P.rep('''    if (s != 1) continue;
''', '''    if (blk || (f[10].length() == 0 && f[12].length() == 0)) continue;          // 0.3.38: the health / ability block from the first line that carries it
    blk = true;
    if (s == 0) sh = sh + "q";          // 0.3.38: q = the block sits under the pet card
''')
# ---- petsH: the block counts under either card
P.rep('''  if (s) {
    h = h + r[1];
    if (f.indexOf('h') >= 0) h = h + r[6] + r[5] + r[7];
    if (f.indexOf('a') >= 0) h = h + r[6] + r[5] + r[7];
  }
  return h + r[0];''', '''  if (s) h = h + r[1];
  if (s || f.indexOf('q') >= 0) {          // 0.3.38: the health / ability block under the card that carries it
    if (f.indexOf('h') >= 0) h = h + r[6] + r[5] + r[7];
    if (f.indexOf('a') >= 0) h = h + r[6] + r[5] + r[7];
  }
  return h + r[0];''')
# ---- petsBody: the block right under its card; the gap to the mount card after it
P.rep('''    if (s == 0) { if (f.indexOf('s') >= 0) y = y + r[2]; continue; }
    if (f.indexOf('h') >= 0) {''', '''    boolean onP = f.indexOf('q') >= 0;          // 0.3.38
    if (s == 0 && !onP) { if (f.indexOf('s') >= 0) y = y + r[2]; continue; }
    if (s == 1 && onP) continue;
    if (f.indexOf('h') >= 0) {''')
P.rep('''      y = y + r[7];
    }
  }
  return sb.toString();
}""".replace("@NAMECOL@", PET_NAMECOL).replace("@NONE@", PET_NONE)''', '''      y = y + r[7];
    }
    if (s == 0 && f.indexOf('s') >= 0) y = y + r[2];          // 0.3.38: the gap to the mount card after the pet card's block
  }
  return sb.toString();
}""".replace("@NAMECOL@", PET_NAMECOL).replace("@NONE@", PET_NONE)''')

assert P.s.count("registerSystem(") == SYS0 and P.s.count("registerCommand(") == CMD0, "0.3.38 adds no system / command"
P.finish()
